{
  "checks": [
    {
      "problem": "链路明细按产品上下分成几块铺开,不同产品的同一步骤不在同一水平线上,读者无法并排对照各产品在同一环节的做法,只能来回滚动查找。",
      "A": "解决",
      "B": "没解决"
    }
  ],
  "worse": [
    {
      "version": "A",
      "where": "链路明细",
      "why": "按步号横向对齐后,步骤少的远川银行也被拉成 7 行、与另两家同行并列,顺着读某一家银行的完整流程(例如核对青禾 9 步、或按问题清单找青禾第 5 步)要纵向跨过整节 10 行,比 B 里一家一个连续区块更费滚动;这是换取横向对照的代价,单家串读时确实不如 B 紧凑。"
    }
  ],
  "better": "A",
  "reason": "A 把链路明细改成按步号横向对齐,同一行就是三家银行的同一步,对照哪家在哪一步做什么不用来回滚动;B 仍是一家一块(青禾 9 步、远川 7 步、北辰 10 步各成一大块),想对照同一步就得在三个大块之间翻好几屏。",
  "next": [
    {
      "where": "链路明细(第 1–10 步各行)",
      "task": "对照三家在同一个环节(协议、身份验证、资料填写、绑卡)的做法",
      "why": "横向对齐的是步号不是环节,三家步数不同,绑卡分别落在青禾第 6 步、远川第 5 步、北辰第 8 步,同一环节不在同一行,读者仍要上下找,或回头去查上面的阶段对比表。"
    },
    {
      "where": "链路明细每张卡片下方的说明文字",
      "task": "快速判断这张卡属于哪个环节、要不要细看",
      "why": "说明只写“第 X 步·页面名·输入项数”,没有阶段标签(协议/身份验证/资料/绑卡),跨行比对时要靠页面标题自己判断是否属于同一环节。"
    },
    {
      "where": "问题清单与链路明细之间",
      "task": "按问题清单里的“位置”找到对应截图核对证据",
      "why": "问题清单在链路明细下方十几屏处,位置只写“青禾银行·第 8 步·人脸核验”,要回滚到上方对应行才能看到截图,来回滚动较多。"
    }
  ]
}
